      } catch {
        send({
          type: "session.commentary.append",
          event_id: `result_${delegationId}`,
          delegation_id: delegationId,
          content: "Something went wrong on my side. Could you say that again?",
        });
      } finally {
        pendingRef.current = Math.max(0, pendingRef.current - 1);
      }
    },
